custom_css:
/* ============================================================
   玻璃青苹果 @Mayonnaise
   非常感谢导航楼内各位老师的分享，所使用代码已在以下标注作者❤︎
============================================================ */
@import url("https://fontsapi.zeoseven.com/184/main/result.css");

:root {
    --头像框: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/1_1.png');
    --思维链文本: '🍏유리 푸른 사과. . .';
    --三点按钮: '────୨';
    --编辑按钮: 'ৎ────';
    --底栏文字: '＋。ʚ🍏✧*';
    --logo1: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/%E6%8F%92%E7%94%BB3.png');
    --logo2: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/%E6%8F%92%E7%94%BB1.png');
    --logo3: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/160151a4-fbc0-411e-9088-4225ebad93c4.png');
    --bg1: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/a7a26095-cb54-4ffb-9466-604b503e273e.png');
    --bg2: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/5eed182c-35a7-430f-94e4-ef217a2cdc7e.png');
}

body {
    font-family: "975Maru SC";
    font-weight: normal;
}

::selection {
    background: var(--SmartThemeQuoteColor);
}

/* ============================================================
   2. 消息气泡与头像系统
   ============================================================ */
#chat{
    background: transparent;
    border: none;
    backdrop-filter: none;
    margin-left: 7px;
    margin-right: 7px;
}

.mes {
    backdrop-filter: blur(7px);
    margin-top: 110px;
    margin-bottom: 40px;
    padding: 0;
    border-radius: 7px;
    background-color: #ffffff20;
    box-shadow: inset 0 0 5px #ffffff70;
    border: 1px solid #ffffff99;
    transform-style: preserve-3d;
    position: relative;
}

.mes::before {
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/d348947a-96b7-4e41-93af-5d9a90b88a62.png');
    background-size: contain;
    background-repeat: no-repeat;
    width: 150px;
    height: 120px;
    position: absolute;
    right: 0;
    bottom: -10px;
    pointer-events: none;
}

.mes::after {
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E7%8E%BB%E7%92%83%E9%9D%92%E8%8B%B9%E6%9E%9C/unnamed.png');
    background-size: contain;
    background-repeat: no-repeat;
    width: 160px;
    height: 120px;
    position: absolute;
    left: 0;
    top: -12px;
    pointer-events: none;
}

.mes[is_user="true"]::before {
    right: auto;
    left: 0;
    transform: scaleX(-1); 
}

.mes[is_user="true"]::after {
    left: auto;
    right: 0;
    transform: scaleX(-1); 
}

.mes.selected { background: #BCCFB490 !important; }

/* 去除最后一条消息和内容之间的间距byblue老师 */
.mes.last_mes > *:not(.mes_block) { padding-bottom: 0; }

.last_mes {
    margin-bottom: 40px !important;
}

.mes .avatar {
    width: 70px;
    height: 70px;
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    top: -100px;
}

.mes .avatar::before {
    content: '';
    background-image: var(--头像框);
    background-size: contain;
    background-repeat: no-repeat;
    width: 79px;
    height: 79px;
    position: absolute;
    left: -5px;
    top: 0px;
}

.mes .avatar img {
    width: 70px;
    height: 70px;
    border: none;
    box-shadow: 0 0 5px #ACDF9B;
}

.mes_block {
    background: var(--SmartThemeChatTintColor);
    margin: 10px;
    border-radius: 7px;
    padding-top: 15px;
    padding-bottom: 7px;
}

.mes_block::before {
    content: '';
    width: 95%;
    height: 22px;
    top: -12px;
    left: 50%;
    transform: translateX(-50%) translateZ(-1px);
    position: absolute;
    z-index: -1 !important;
    border-radius: 3px 3px 0 0;
    background-image: var(--bg2);
    background-size: 50%;
    background-position: center;
    box-shadow: inset 0 0 3px #E1D7DB;
    -webkit-mask-image: linear-gradient(to bottom, black 0%, black calc(100% - 11px), rgba(0, 0, 0, 0.8) calc(100% - 11px), rgba(0, 0, 0, 0.8) 100%);
    mask-image: linear-gradient(to bottom, black 0%, black calc(100% - 11px), rgba(0, 0, 0, 0.8) calc(100% - 11px), rgba(0, 0, 0, 0.6) 100%);
}

@media (max-width: 600px) {
    .mes_block::before {
        width: 93%;
    }
}

.mes_text {
    padding: 10px;
    margin-right: 10px;
    margin-bottom: 30px;
    border-bottom: 1px solid #E1D7DB;
}

.mes .name_text {
    position: absolute;
    top: 17px;
    font-size: 15px;
    left: 50%;
    transform: translateX(-50%);
}

/* ============================================================
   3. 消息功能组件（翻页、时间、状态）
   ============================================================ */
/* 翻页图标替换二改by 眠N勿扰老师 */
.swipe_left::before {
    top: -12px;
    left: -26px;
    clip-path: polygon(0 0, 0 100%, 100% 100%);
    border-radius: 0 0 0 7px;
}

.swipe_left, .swipe_right { position: absolute !important; opacity: 1 !important; }

.swipe_right::before {
    top: -5px;
    right: -40px;
    clip-path: polygon(100% 0, 100% 100%, 0 100%);
    border-radius: 0 0 7px 0;
}

.swipe_right::before, .swipe_left::before {
    content: '' !important;
    width: 50px;
    height: 50px;
    position: absolute;
    background-image: var(--bg2);
    background-size: cover;
    box-shadow: inset 0 -3px 5px #B4C8AD95;
}

.swipe_right { margin-right: 36px; bottom: 21px; }
.swipe_left { bottom: 14px; margin-left: 7px; }

[is_user="false"] .swipes-counter {
    white-space: nowrap;
    position: absolute !important;
    bottom: 19px;
    right: 40px;
    font-family: "975Maru SC";
    opacity: 0!important;
    color: #B4C8AD;
    font-weight: normal;
    font-size: 10px;
    background-color: rgba(255, 255, 255, 0.9);
    box-shadow: 0 1px 3px #B4C8AD90;
    padding: 1.3px;
    border-radius: 3px;
    transition: opacity 0.4s ease!important;
    white-space: nowrap;
}

.mes:hover .swipes-counter { opacity: 1!important; }

.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay, .timestamp {
    position: absolute;
    top: 3px;
    opacity: 1;
    color: #B4C8AD;
    font-weight: normal;
    font-size: 10px;
    background-color: rgba(255, 255, 255, 0.9);
    box-shadow: 0 1px 3px #B4C8AD90;
    padding: 1.3px;
    border-radius: 3px;
    min-width: 35px;
    z-index: 1;
}

.timestamp::before { content: '⍀'; }
.mesIDDisplay { right: 20px; }
.tokenCounterDisplay { right: 58px; }
.mes_timer { right: 96px; }
.timestamp { left: 20px; }

.mes_timer:empty, .mes_timer[style*="display: none"],.tokenCounterDisplay:empty, .tokenCounterDisplay[style*="display: none"] { display: none !important; }

/* ============================================================
   4. 顶栏样式
   ============================================================ */
#top-bar {
    top: 3px;
    backdrop-filter: blur(7px);
    border-radius: 15px;
    background-color: #ffffff20;
    box-shadow: inset 0 0 5px #ffffff70;
    border: 1px solid white;
}

#top-bar::before {
    content: '';
    background-image: var(--bg1);
    background-size: 22%;
    background-position: center;
    position: absolute;
    width: 99%;
    height: 78%;
    border-radius: 15px;
    top: 3px;
    left: 50%;
    transform: translateX(-50%);
}

@media (max-width: 600px) {
    #top-bar::before { width: 98.5%; }
}

/* 顶栏图标替换by 秦素老师 */
#top-settings-holder > div > :first-child {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    width: 25px !important;
    height: 25px !important;
    margin-top: 2px;
    transition: filter 0.5s ease;
}

#top-settings-holder > div > :first-child > * {
    opacity: 0 !important;
}

#top-settings-holder > .drawer:nth-of-type(odd) .drawer-toggle {
    background-image: var(--logo1) !important;
}

#top-settings-holder > .drawer:nth-of-type(even) .drawer-toggle {
    background-image: var(--logo2) !important;
}

#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer:has(.drawer-content.openDrawer) .drawer-toggle {
    filter: drop-shadow(0 0 3px #B4C8AD);
}

/* ============================================================
   5. 底栏与输入框
   ============================================================ */
#send_form {
    backdrop-filter: blur(7px);
    border-radius: 23px;
    background-color: #ffffff20;
    box-shadow: inset 0 0 5px #ffffff70;
    border: 1px solid white;
    bottom: 3px;
    position: absolute;
    width: 95%;
    left: 50%;
    transform: translate(-50%);
}

#send_form::before {
    content: '';
    background-image: var(--bg1);
    background-size: 22%;
    background-position: center;
    position: absolute;
    width: 99.5%;
    height: 90%;
    border-radius: 23px;
    left: 50%;
    transform: translateX(-50%);
}

#send_form:focus-within::before {
    background-image: none;
    background-color: white;
}

/* 输入框文字by hgu老师 */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }

#nonQRFormItems { position: relative !important; }

#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
    content: var(--底栏文字);
    font-size: 14px;
    white-space: nowrap;
    opacity: 0.7;
    position: absolute;
    z-index: 10;
    pointer-events: none;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* 隐藏QR栏二改by 12老师 */
#qr--bar {
    max-height: 0 !important;
    opacity: 0 !important;
    pointer-events: none;
    transition: all 2s !important;
    cubic-bezier(0.175, 0.885, 0.32, 1.275)
}

#send_form:focus-within #qr--bar {
    max-height: 120px !important;
    opacity: 1 !important;
    pointer-events: auto;
}

/* ============================================================
   6. 按钮与交互图标
   ============================================================ */
.mes_buttons {
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    opacity: 1;
    gap: 0;
    z-index: 1;
    font-size: 11px;
}

.mes_button {
    filter: none !important;
    color: #B4C8AD;
    opacity: 0.9;
}

.mes_edit::before {
    content: var(--编辑按钮) !important;
}

.extraMesButtonsHint::before {
    content: var(--三点按钮) !important;
}

.mes_edit_buttons {
    position: absolute;
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%) scale(0.8);
    filter: none;
}

/* 底栏图标替换by 墨千尾老师 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
.fa-solid.fa-circle-stop::before,
#quick-reply-rocket-button > i {
    display: none !important;
    content: '' !important;
}

#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button,
.fa-solid.fa-circle-stop {
    width: 21px !important;
    height: 21px !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    opacity: 1 !important;
    transition: filter 0.5s ease !important;
    margin-top: auto !important;
    margin-bottom: auto !important;
}

#options_button, #extensionsMenuButton { background-image: var(--logo1); }
#quick-reply-rocket-button { background-image: var(--logo3); }
#send_but { background-image: var(--logo2); }

.fa-solid.fa-circle-stop {
    background-image: var(--logo2);
    animation: rotate-slow 4s infinite linear !important;
}

#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover,
#quick-reply-rocket-button:hover {
    filter: drop-shadow(0 0 5px #E1D7DB) !important;
}

@keyframes rotate-slow {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

.fa-circle-chevron-down, .inline-drawer-icon.fa-circle-chevron-down {
    background-image: var(--logo3) !important;
    background-size: 16px !important;
    background-position: center !important;
    color: transparent !important;
    transition: transform 0.4s ease-in-out !important;
    filter: none;
}

.fa-circle-chevron-up, .inline-drawer-icon.fa-circle-chevron-up {
    background-image: var(--logo3) !important;
    background-size: 16px !important;
    background-position: center !important;
    color: transparent !important;
    transform: rotate(-90deg) !important;
    transition: transform 0.4s ease-in-out !important;
    filter: none;
}

.menu_button {
    background: #ffffff70 !important;
    color: var(--SmartThemeQuoteColor);
    transition: all 0.4s ease;
}

.menu_button:hover {
    box-shadow: 0 2px 4px 0px var(--SmartThemeQuoteColor);
    color: #fff;
    background: var(--SmartThemeQuoteColor) !important;
}

/* ============================================================
   7. 侧边栏与扩展面板
   ============================================================ */
#left-nav-panel, #right-nav-panel {
    max-height: 100vh !important;
}

#rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #bg-header-fixed, #bg_tabs, #rm_extensions_block, #PersonaManagement, #left-nav-panel, #right-nav-panel {
    background-image: var(--bg2);
    background-size: 75%;
    background-position: center;
    background-color: #ffffff90;
    background-blend-mode: screen;
    border-radius: 7px;
    border: 1px solid white;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header {
    background-image: var(--bg1);
    background-size: 68%;
    background-position: center;
    border-radius: 7px;
    box-shadow: inset 0 0 8px white;
    transition: 0.4s ease !important;
    padding: 4px;
    margin-bottom: 7px;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header:hover {
    padding-left: 7px;
    filter: drop-shadow(0 0 3px var(--SmartThemeQuoteColor));
}

#user-settings-block h4, .standoutHeader {
    background-image: var(--bg1);
    background-size: 68%;
    background-position: center;
    border-radius: 7px;
    box-shadow: inset 0 0 8px white;
}

dialog.popup, #select_chat_popup, .list-group, .select2-dropdown, #options, #extensionsMenu, #completion_prompt_manager_popup, #character_popup {
    background-image: var(--bg2);
    background-size: 75%;
    background-position: center;
    background-color: #ffffff90;
    background-blend-mode: screen;
    box-shadow: none;
}

/* ============================================================
   8. 提示词管理器与思维链
   ============================================================ */
#completion_prompt_manager_list {
    background-image: var(--bg1);
    background-size: 50%;
    background-color: #ffffff90;
    background-blend-mode: screen;
    box-shadow: inset 0 0 50px white;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    background: #ffffff30;
    backdrop-filter: blur(2px);
    box-shadow: inset 0 0 10px white;
    margin-bottom: 10px !important;
    border-radius: 7px;
    padding: 8px !important;
    border: 1px solid #E1D7DB !important;
    transition: padding 0.5s ease;
}

#completion_prompt_manager .completion_prompt_manager_prompt:hover { padding-left: 0px !important; }

.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    box-shadow: 0 1px 5px #B4C8AD70 !important;
}

.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: var(--SmartThemeEmColor) !important;
}

/* 类名by hy老师 */
.completion_prompt_manager_prompt .fa-asterisk, .completion_prompt_manager_prompt .fa-square-poll-horizontal, .completion_prompt_manager_prompt .fa-syringe, .completion_prompt_manager_prompt .fa-thumb-tack {
    color: var(--SmartThemeQuoteColor) !important;
}

/* 类名byMDMA老师 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span, #completion_prompt_manager .completion_prompt_manager_header div, .prompt_manager_prompt_controls span {
    filter: none !important;
    color: var(--SmartThemeBodyColor);
}

.mes_reasoning_header.flex-container {
    display: flex !important;
    border-radius: 13px;
    color: white;
    background: white;
    border: 1px solid #B4C8AD70;
    padding: 2px 9px 2px 9px;
    box-shadow: inset 0 -2px 5px #B4C8AD70;
}

.mes_reasoning_header_title { font-size: 0; }
.mes_reasoning_header_title::before {
    content: var(--思维链文本);
    font-size: 13px;
    color: #B4C8AD95;
}

.mes_reasoning_details {
    position: relative !important;
    width: 95%;
    margin: auto;
}

.mes_reasoning { border-left: 2px solid #B4C8AD70; }
.mes_reasoning_arrow { display: none; }

.mes_reasoning_actions.flex-container {
    position: absolute;
    right: 5px;
    transform: scale(0.8);
}

.mes_reasoning_edit_done, .mes_reasoning_edit_cancel, .mes_reasoning_actions .edit_button, .mes_reasoning_actions .menu_button {
    filter: none !important;
}

/* ============================================================
   9. 输入控件与UI元素
   ============================================================ */
:is(.text_pole,select, input:not([type="checkbox"]), [id*="textarea"]:not(#send_textarea), [class*="textarea"], [class*="select2-selection"],.popup-input) {
    background-color: #ffffff90 !important;
    border-radius: 7px;
    box-shadow: inset 0 0 5px #ffffff70;
    font-family: "975Maru SC";
}

/* 复选框二改by食南瓜者老师 */
input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 14px;
    height: 14px;
    border: 1px solid #C6CDC4;
    background: transparent;
    transition: all 0.2s ease;
    position: relative;
}

input[type="checkbox"]:checked { background: #94AC8B; }
input[type="checkbox"]::after, input[type="checkbox"]::before { content: none !important; }
input[type="checkbox"]:checked::after {
    content: '❤︎' !important;
    display: block !important;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 9px;
    color: white;
}
input[type="checkbox"]:hover { border-color: #B4C8AD; }

/* 滑动条by 墨千尾老师 */
input[type="range"] { filter: none !important; }

input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 7px;
    background: white; 
    border-radius: 3px;
    border: 1px solid #B4C8AD70;
    box-shadow: inset 0 -1px 2.5px #B4C8AD;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    top: -8px;
    height: 22px;
    width: 22px;
    background-image: var(--logo1);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    transition: all 0.5s ease-in-out;
}

input[type="range"]:hover::-webkit-slider-thumb { filter: drop-shadow(0 0 3px #E1D7DB); }

select option { font-family: "975Maru SC"; color: var(--SmartThemeBodyColor) !important; background-color: #fff !important; }

.avatar-container.interactable { transition: padding 0.5s ease; }
.avatar-container.interactable:hover { padding-left: 10px; filter: drop-shadow(0 0 3px var(--SmartThemeQuoteColor)); }

.avatar-container.interactable.selected {
    background: #ffffff10;
    backdrop-filter: blur(5px);
    border: 1px solid var(--SmartThemeBorderColor);
}

/* 滚动条by墨千尾老师 */
::-webkit-scrollbar { width: 7px; }

::-webkit-scrollbar-thumb {
    box-shadow: inset 0 -1px 2.5px #B4C8AD!important; 
    background: white !important; 
    border: 1px solid #B4C8AD70!important; 
}

#chat::-webkit-scrollbar-thumb {
    box-shadow: inset -1px 0 3px #E1D7DB90 !important;
}

@media (max-width: 600px) {
    #chat::-webkit-scrollbar { display: none; }
}

/* ============================================================
   10. 文本格式与内容装饰
   ============================================================ */
.mes_text q {
    display: inline;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
    border-radius: 13px;
    background: white;
    border: 1px solid #B4C8AD50;
    padding: 2px 9px 2px 9px;
    box-shadow: inset 0 -1px 4px #B4C8AD60;
    line-height: calc(var(--mainFontSize) + .7rem);
}

pre code, code { background: white !important; }
code { color: var(--SmartThemeBodyColor); font-family: "975Maru SC"; }
.mes_text blockquote { background: white; }

/* ============================================================
   11. 系统状态与反馈
   ============================================================ */
/* 加载图标修改by serein老师 */
#load-spinner {
    --spinner-size: 40px;
    transition: all var(--animation-duration-2x) ease-out;
    opacity: 1;
    top: calc(50% - var(--spinner-size) / 2);
    left: calc(50% - var(--spinner-size) / 2);
    position: absolute;
    width: var(--spinner-size);
    height: var(--spinner-size);
    background-image: var(--logo2);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

#load-spinner::before { display: none !important; }

/* 通知美化by serein老师 */
.toast {
    background-color: #ffffff95 !important;
    color: var(--SmartThemeBodyColor) !important;
    border: 1px solid #E1D7DB;
    box-shadow: none !important;
    transition: filter 0.8s ease !important;
    backdrop-filter: blur(8px);
}

#toast-container > .toast {
    background-image: var(--logo2) !important;
    background-size: 22px 25px !important;
    background-position: 15px center !important;
}

#toast-container > .toast:before { display: none; }
.toast:hover { filter: drop-shadow(0 0 3px #BCCFB4) !important; }

.reverse_proxy_warning { background: white !important; color: var(--SmartThemeQuoteColor) !important; }
